@extends('layouts.customer') @section('title','Payment details') @section('content')<div class="row justify-content-center"><div class="col-xl-8"><div class="gsm-card p-4 p-lg-5"><div class="d-flex justify-content-between align-items-start"><div><div class="text-muted small">PAYMENT REFERENCE</div><h1 class="h4 fw-bold">{{ $payment->uuid }}</h1></div><span id="paymentStatus" class="status-pill status-{{ $payment->status }}">{{ ucfirst($payment->status) }}</span></div><hr><div class="row g-4"><div class="col-md-6"><div class="text-muted small">Method</div><div class="fw-bold">{{ $payment->gateway?->name }}</div></div><div class="col-md-6"><div class="text-muted small">Total</div><div class="fw-bold">{{ $payment->payable_currency }} {{ $payment->currency_code }}</div></div>@if($payment->gateway?->driver==='usdt')<div class="col-12"><div class="alert alert-primary"><div class="small">Send exactly</div><div class="h3 fw-bold">{{ data_get($payment->metadata,'provider_order.amount',$payment->payable_currency) }} USDT</div><div><strong>Network:</strong> {{ data_get($payment->metadata,'provider_order.network') }}</div><div class="text-break"><strong>Address:</strong> {{ data_get($payment->metadata,'provider_order.address') }}</div><div class="small mt-2">The payment is confirmed automatically after the required blockchain confirmations.</div></div></div>@elseif(!$payment->gateway?->is_system)<div class="col-12"><div class="alert alert-info"><strong>Payment instructions</strong><div class="mt-2" style="white-space:pre-wrap">{{ data_get($payment->metadata,'payment_details') ?: $payment->gateway?->instructions }}</div></div></div>@endif</div><div class="d-flex gap-2 mt-4"><a class="btn btn-outline-secondary" href="{{ route('customer.payments.index') }}">Payment history</a>@if($payment->status!=='paid')<a class="btn btn-gsm" href="{{ route('customer.payments.create') }}">Start another payment</a>@endif</div></div></div></div>@if($payment->status==='pending')@push('scripts')<script>setInterval(async()=>{const r=await fetch(@json(route('customer.payments.status',$payment)),{headers:{Accept:'application/json'}});if(!r.ok)return;const j=await r.json();if(j.status==='paid')location.reload();document.getElementById('paymentStatus').textContent=j.status[0].toUpperCase()+j.status.slice(1)},10000)</script>@endpush@endif@endsection
